const out=dir+'/'+name+'.config.json',config={schemaVersion:1,diagnosticOnly:true,compilerAccepted:false,performanceAccepted:false,baselineRestoration:'360e326c',request,requestSha256:hash(request),plugins:files.slice(1),pins,limits:authority.limits,worker:{stackMiB:256,oldMiB:6144,youngMiB:128},expectedOutputSha256:authority.expectedSelfhostOutput};
