import { readFileSync } from 'node:fs';
import { createHash } from 'node:crypto';

// Diagnostic only. Never imports/evaluates the target or invokes target closures.
const IMAGE_SHA = '85aff9e534c18b4a1d6acac5f3237571dabc58f2c1a75a7ea2040f1c477ab60e';
const HOOK = '__allE13ArenaFields';
const PREFIX = '../bend2/selfhost/checker_arena.';
const PHASES = ['startup', 'load-parse', 'expand', 'check', 'inspect', 'emit', 'complete', 'other'];
const CANDIDATES = ['family_arity_view', 'initial_telescope_count_view', 'drop_telescope_view'];
let state;
const assert = (ok, message) => { if (!ok) throw new Error('E13: ' + message); };
const sha = text => createHash('sha256').update(text).digest('hex');
const esc = text => text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

// A bounded lexical delimiter scan of generated function bodies, not a JS parser.
// R12 generated bodies have JSON string literals, no regex or template literals.
// String/comment bytes are blanked for identifier-use analysis; lengths stay exact.
function structure(text, start) {
  const stack = [], pairs = new Map();
  let quote = '', comment = '', masked = '', i = start;
  for (; i < text.length; i++) {
    const c = text[i], n = text[i + 1];
    if (comment === 'line') {
      masked += c === '\n' ? '\n' : ' ';
      if (c === '\n') comment = '';
      continue;
    }
    if (comment === 'block') {
      masked += ' ';
      if (c === '*' && n === '/') { masked += ' '; i++; comment = ''; }
      continue;
    }
    if (quote) {
      masked += ' ';
      if (c === '\\') { masked += ' '; i++; }
      else if (c === quote) quote = '';
      continue;
    }
    if (c === '"' || c === "'") { quote = c; masked += ' '; continue; }
    assert(c !== '`', 'unsupported template literal in generated function');
    if (c === '/' && n === '/') { comment = 'line'; masked += '  '; i++; continue; }
    if (c === '/' && n === '*') { comment = 'block'; masked += '  '; i++; continue; }
    masked += c;
    if (c === '{') stack.push(i);
    if (c === '}') {
      assert(stack.length, 'unbalanced generated function');
      pairs.set(stack.pop(), i);
      if (!stack.length) return { end: i + 1, pairs, masked };
    }
  }
  throw new Error('E13: unterminated generated function');
}

function indexImage(source) {
  const functions = new Map(), names = new Map(), fields = new Map();
  for (const m of source.matchAll(/^\$FIELDS\[("[^"\n]+")\]=(\[[^\n]*?\]);/gm)) {
    const tag = JSON.parse(m[1]);
    if (new RegExp('^' + esc(PREFIX) + '(?:Term[A-Za-z]+|Body[A-Za-z]+|PatternVar|PatternCtr)$').test(tag)) {
      assert(!fields.has(tag), 'duplicate field declaration: ' + tag);
      fields.set(tag, JSON.parse(m[2]));
    }
  }
  for (const m of source.matchAll(/^\$D\[("[^"\n]+")\]=([^\n]*)/gm)) {
    const ids = [...new Set(m[2].match(/\$b\d+(?=\()/g) || [])];
    if (ids.length === 1) {
      const id = ids[0];
      if (!names.has(id)) names.set(id, []);
      names.get(id).push(JSON.parse(m[1]));
    }
  }
  for (const m of source.matchAll(/^function (\$[bk]\d+)\(([^)\n]*)\)\{/gm)) {
    assert(!functions.has(m[1]), 'duplicate generated declaration ' + m[1]);
    const open = m.index + m[0].length - 1;
    const scan = structure(source, open);
    const text = source.slice(m.index, scan.end);
    const masked = m[0].slice(0, -1) + scan.masked;
    functions.set(m[1], { id: m[1], start: m.index, open, end: scan.end,
      text, masked, pairs: scan.pairs, names: names.get(m[1]) || [] });
  }
  assert(fields.size === 31, 'expected R12 29 Node and two Pattern variants');
  return { functions, names, fields };
}

const isSemantic = name => !/checker_(?:match|continuation|deforest_(?:match|cont))_/.test(name);
function contextResolver(index) {
  const parents = new Map(), cache = new Map();
  for (const fn of index.functions.values()) {
    for (const target of new Set(fn.masked.match(/\$[bk]\d+/g) || [])) {
      if (target === fn.id || !index.functions.has(target)) continue;
      if (!parents.has(target)) parents.set(target, new Set());
      parents.get(target).add(fn.id);
    }
  }
  return id => {
    if (cache.has(id)) return cache.get(id);
    const seen = new Set([id]);
    let frontier = [id], roots = [], bounded = false;
    for (let depth = 0; frontier.length && depth <= 12; depth++) {
      const next = [];
      for (const current of frontier) {
        const semantic = (index.names.get(current) || []).filter(isSemantic);
        if (semantic.length) roots.push(...semantic);
        else for (const parent of parents.get(current) || []) {
          if (!seen.has(parent)) { seen.add(parent); next.push(parent); }
        }
      }
      if (roots.length) break; // nearest static semantic parents, NOT dynamic callers
      if (seen.size > 4096 || depth === 12) { bounded = next.length > 0; break; }
      frontier = next;
    }
    roots = [...new Set(roots)].sort();
    const result = { names: index.names.get(id) || [], staticContexts: roots.slice(0, 12),
      contextCount: roots.length, contextBounded: bounded || roots.length > 12 };
    cache.set(id, result);
    return result;
  };
}

function phaseIndex() {
  const p = PHASES.indexOf(globalThis.__allExperimentPhase || 'startup');
  return p < 0 ? PHASES.length - 1 : p;
}

export function instrument(source, context) {
  assert(!state && !globalThis[HOOK], 'instrument called twice in one worker');
  assert(context && typeof context.image === 'string', 'context.image is required');
  const pinned = readFileSync(context.image);
  assert(sha(pinned) === IMAGE_SHA, 'only the immutable accepted R12 image is supported');
  assert(!source.includes('globalThis.' + HOOK), 'hook prefix already present');
  const index = indexImage(source);
  const resolveContext = contextResolver(index);
  const sites = [], insertions = [], observedKinds = new Set();
  const coverage = { switchCases: 0, guardedCases: 0, unsupportedCases: [], getterSites: 0 };
  const candidateIds = new Map();
  for (const candidate of CANDIDATES) {
    const entries = [...index.functions.values()].filter(fn => fn.names.includes('checker_core_steps_v1.checker_body_' + candidate));
    assert(entries.length === 1, 'unique candidate binding missing: ' + candidate);
    candidateIds.set(candidate, entries[0].id);
  }
  const add = (fn, offset, detail, suffix = '') => {
    assert(sites.length < 8192, 'static site cap exceeded');
    const id = sites.length;
    sites.push({ id, function: fn.id, ...resolveContext(fn.id), ...detail });
    insertions.push({ at: offset, text: `globalThis.${HOOK}.${suffix ? 'read' : 'hit'}(${id}${suffix});` });
    return id;
  };

  // Successful constructor-match arms. Count the existing unconditional field
  // projection prologue AFTER its final read, without evaluating fields again.
  function branch(fn, tag, variable, bodyStart, bodyEnd, shape) {
    if (!index.fields.has(tag)) return;
    const declared = index.fields.get(tag);
    let pos = bodyStart;
    if (shape === 'switch') {
      const label = /^\$case\d+:\{/.exec(source.slice(pos, pos + 80));
      assert(label, 'unexpected R12 switch case label in ' + fn.id);
      pos += label[0].length;
      const truth = /^const \$v\d+=true;/.exec(source.slice(pos, pos + 80));
      assert(truth, 'unexpected R12 case prologue in ' + fn.id);
      pos += truth[0].length;
    }
    const projections = [];
    const projection = new RegExp('^const (\\$[A-Za-z_][\\w$]*)=' + esc(variable) + '\\.([A-Za-z_][\\w$]*);');
    for (;;) {
      const m = projection.exec(source.slice(pos, Math.min(pos + 160, bodyEnd)));
      if (!m) break;
      assert(declared.includes(m[2]), 'unknown arena field ' + tag + '.' + m[2]);
      projections.push({ field: m[2], alias: m[1] });
      pos += m[0].length;
    }
    const tokens = new Map();
    for (const token of fn.masked.match(/\$[A-Za-z_][\w$]*/g) || []) tokens.set(token, (tokens.get(token) || 0) + 1);
    const used = projections.filter(p => tokens.get(p.alias) > 1).map(p => p.field);
    const fields = projections.map(p => p.field);
    // Projections later in this arm are not assigned the unconditional count.
    const later = new RegExp(esc(variable) + '\\.(' + declared.map(esc).join('|') + ')(?![\\w$])', 'g');
    const laterReads = declared.length ? [...source.slice(pos, bodyEnd).matchAll(later)].length : 0;
    add(fn, pos, { metric: 'matchedDescriptor', shape, kind: tag.slice(PREFIX.length),
      category: tag.includes('.Pattern') ? 'pattern' : 'node', declaredFields: declared,
      projectedFields: fields, referencedProjectionFields: used,
      uninstrumentedLaterProjectionSites: laterReads,
      unconditionalProjectionCoverage: fields.length === declared.length && laterReads === 0 });
    observedKinds.add(tag);
  }

  for (const fn of index.functions.values()) {
    const switches = [...fn.text.matchAll(/switch\((\$[A-Za-z_][\w$]*)\?\.\$\)\{/g)].map(m => {
      const open = fn.start + m.index + m[0].length - 1;
      return { variable: m[1], open, end: fn.pairs.get(open) };
    });
    for (const m of fn.text.matchAll(/case ("\.\.\/bend2\/selfhost\/checker_arena\.[A-Za-z]+"):\{/g)) {
      const tag = JSON.parse(m[1]);
      if (!index.fields.has(tag)) continue;
      const at = fn.start + m.index;
      const enclosing = switches.filter(s => s.open < at && at < s.end).sort((a, b) => b.open - a.open)[0];
      assert(enclosing, 'arena switch without exact discriminant in ' + fn.id);
      const open = at + m[0].length - 1;
      branch(fn, tag, enclosing.variable, open + 1, fn.pairs.get(open), 'switch');
      coverage.switchCases++;
    }
    const guard = /const (\$[A-Za-z_][\w$]*)=\((\$[A-Za-z_][\w$]*)&&\2\.\$===("\.\.\/bend2\/selfhost\/checker_arena\.[A-Za-z]+")\);if\(\1\)\{/g;
    let guarded = 0;
    for (const m of fn.text.matchAll(guard)) {
      const tag = JSON.parse(m[3]);
      if (!index.fields.has(tag)) continue;
      const open = fn.start + m.index + m[0].length - 1;
      branch(fn, tag, m[2], open + 1, fn.pairs.get(open), 'guard');
      guarded++;
      coverage.guardedCases++;
    }
    const expectedGuards = [...fn.text.matchAll(/\.\$===("\.\.\/bend2\/selfhost\/checker_arena\.[A-Za-z]+")/g)]
      .filter(m => index.fields.has(JSON.parse(m[1]))).length;
    if (guarded !== expectedGuards) coverage.unsupportedCases.push({ function: fn.id, expected: expectedGuards, covered: guarded });
  }
  assert(!coverage.unsupportedCases.length, 'unsupported arena guard syntax: ' + JSON.stringify(coverage.unsupportedCases));
  assert(observedKinds.size === index.fields.size, 'not all arena descriptor kinds have matched-arm sites');

  // Observe the already-returned Array.get result exactly once at both actual
  // storage accessors. This is boxed descriptor retrieval, NOT packed decoding.
  for (const accessor of ['get_node', 'get_pattern']) {
    const name = PREFIX + accessor;
    const entries = [...index.functions.values()].filter(fn => fn.names.includes(name));
    assert(entries.length === 1, 'unique accessor mapping missing: ' + name);
    const fn = entries[0];
    const gets = [...fn.text.matchAll(/const (\$v\d+)=\$p_array_get\((\$v\d+),(\$v\d+)\);/g)];
    assert(gets.length === 1, 'expected exactly one primitive get in ' + name);
    const get = gets[0];
    add(fn, fn.start + get.index + get[0].length,
      { metric: 'boxedRetrieval', accessor, category: accessor === 'get_node' ? 'node' : 'pattern' }, ',' + get[1] + '.snd');
    coverage.getterSites++;
  }

  // Distinct semantic entry counters: do not sum these with branch/read counts.
  const watched = /(?:checker_(?:pure|body)_)?(?:arena_(?:decode_(?:term|pattern|checked_node|occurrence)|words_view|names_view|naturals_view|quantities_view|publish_occurrence|release)|inspect_checked|family_arity_view|initial_telescope_count_view|drop_telescope_view)$/;
  for (const fn of index.functions.values()) {
    const names = fn.names.filter(name => watched.test(name.split('.').at(-1)) ||
      new RegExp('^' + esc(PREFIX) + '(?:metadata_read|metadata_write|rewind|node_bound|bound_read|node_is_closed)$').test(name));
    if (names.length) add(fn, fn.open + 1, { metric: 'invocation', watchedNames: names });
  }

  const kindTags = [...index.fields.keys()];
